          ).map(([id, label]) => (
            <button
              key={id}
              type="button"
              onClick={() => setLadderMetric(id)}
              className={`rounded-md px-2.5 py-1 text-xs font-medium ${
                ladderMetric === id
                  ? "bg-slate-800 text-white"
                  : "bg-slate-100 text-slate-600 hover:bg-slate-200"
              }`}
            >
              {label}
            </button>
          ))}
        </div>
      )}

      <div className="h-[360px] w-full sm:h-[420px]">
        {panel === "gap-path" && (
          <ResponsiveContainer width="100%" height="100%">
            <ComposedChart data={COHORT_SERIES} margin={{ top: 8, right: 12, left: 0, bottom: 0 }}>
              <CartesianGrid stroke={COLORS.grid} strokeDasharray="3 3" />
              <XAxis dataKey="year" tick={{ fontSize: 12 }} />
              <YAxis
                yAxisId="burden"
                domain={[38, 56]}
                tick={{ fontSize: 12 }}
                tickFormatter={(v) => `${v}%`}
                label={{ value: "Burden %", angle: -90, position: "insideLeft", fontSize: 11 }}
              />
              <YAxis
                yAxisId="gap"
                orientation="right"
                domain={[0, 12]}
                tick={{ fontSize: 12 }}
                tickFormatter={(v) => `${v}`}
                label={{ value: "Gap pp", angle: 90, position: "insideRight", fontSize: 11 }}
              />
              <Tooltip
                formatter={(value, name) => {
                  const n = Number(value ?? 0);
                  return name === "gapPp"
                    ? [fmtPp(n), "Gap"]
                    : [fmtPct(n), String(name)];
                }}
              />
              <Legend />
              <Area
                yAxisId="gap"
                type="monotone"
                dataKey="gapPp"
                name="Gap (pp)"
                fill="#ede9fe"
                stroke={COLORS.gap}
                strokeWidth={2}
              />
              <Line
                yAxisId="burden"
                type="monotone"
                dataKey="interior"
                name="Interior median"
                stroke={COLORS.interior}
                strokeWidth={2.5}
                dot={{ r: 3 }}
              />
              <Line
                yAxisId="burden"
                type="monotone"
                dataKey="coastal"
                name="Coastal median"
                stroke={COLORS.coastal}
                strokeWidth={2.5}
                dot={{ r: 3 }}
              />
            </ComposedChart>
          </ResponsiveContainer>
