                tick={{ fontSize: 12 }}
                tickFormatter={(v) => `${v}%`}
              />
              <Tooltip formatter={(v) => fmtPct(Number(v ?? 0))} />
              <Legend />
              <Line
                type="monotone"
                dataKey="coastalMedian"
                name="Coastal median"
                stroke={COLORS.coastal}
                strokeDasharray="6 4"
                strokeWidth={1.5}
                dot={false}
              />
              <Line
                type="monotone"
                dataKey="interiorMedian"
                name="Interior median"
                stroke={COLORS.interior}
                strokeDasharray="6 4"
                strokeWidth={1.5}
                dot={false}
