                }}
              />
              <Scatter data={scatterData} name="Metros">
                {scatterData.map((r) => (
                  <Cell
                    key={r.id}
                    fill={r.cohort === "interior" ? COLORS.interior : COLORS.coastal}
                  />
                ))}
              </Scatter>
            </ScatterChart>
          </ResponsiveContainer>
