        <div className="flex flex-wrap gap-2">
          {(
            [
              ["all", "All metros"],
              ["interior", "Interior"],
              ["coastal", "Coastal"],
            ] as const
          ).map(([id, label]) => (
            <button
              key={id}
              type="button"
              onClick={() => setCohortFilter(id)}
              className={`rounded-md px-2.5 py-1 text-xs font-medium ${
                cohortFilter === id
                  ? "bg-slate-800 text-white"
                  : "bg-slate-100 text-slate-600 hover:bg-slate-200"
              }`}
            >
              {label}
            </button>
          ))}
        </div>
      )}

      {panel === "rise-ladder" && (
        <div className="flex flex-wrap gap-2">
          {(
            [
              ["delta", "Burden rise (pp)"],
              ["zori", "ZORI cum %"],
            ] as const
          ).map(([id, label]) => (
            <button
              key={id}
              type="button"
              onClick={() => setLadderMetric(id)}
              className={`rounded-md px-2.5 py-1 text-xs font-medium ${
                ladderMetric === id
                  ? "bg-slate-800 text-white"
                  : "bg-slate-100 text-slate-600 hover:bg-slate-200"
              }`}
            >
              {label}
            </button>
          ))}
        </div>
      )}

      <div className="h-[360px] w-full sm:h-[420px]">
        {panel === "gap-path" && (
          <ResponsiveContainer width="100%" height="100%">
            <ComposedChart data={COHORT_SERIES} margin={{ top: 8, right: 12, left: 0, bottom: 0 }}>
              <CartesianGrid stroke={COLORS.grid} strokeDasharray="3 3" />
              <XAxis dataKey="year" tick={{ fontSize: 12 }} />
              <YAxis
                yAxisId="burden"
                domain={[38, 56]}
                tick={{ fontSize: 12 }}
                tickFormatter={(v) => `${v}%`}
                label={{ value: "Burden %", angle: -90, position: "insideLeft", fontSize: 11 }}
              />
              <YAxis
                yAxisId="gap"
                orientation="right"
                domain={[0, 12]}
                tick={{ fontSize: 12 }}
                tickFormatter={(v) => `${v}`}
                label={{ value: "Gap pp", angle: 90, position: "insideRight", fontSize: 11 }}
              />
              <Tooltip
                formatter={(value, name) => {
                  const n = Number(value ?? 0);
                  return name === "gapPp"
                    ? [fmtPp(n), "Gap"]
                    : [fmtPct(n), String(name)];
                }}
              />
              <Legend />
              <Area
                yAxisId="gap"
                type="monotone"
                dataKey="gapPp"
                name="Gap (pp)"
                fill="#ede9fe"
                stroke={COLORS.gap}
                strokeWidth={2}
              />
              <Line
                yAxisId="burden"
                type="monotone"
                dataKey="interior"
                name="Interior median"
                stroke={COLORS.interior}
                strokeWidth={2.5}
                dot={{ r: 3 }}
              />
              <Line
                yAxisId="burden"
                type="monotone"
                dataKey="coastal"
                name="Coastal median"
                stroke={COLORS.coastal}
                strokeWidth={2.5}
                dot={{ r: 3 }}
              />
            </ComposedChart>
          </ResponsiveContainer>
        )}

        {panel === "metro-path" && (
          <ResponsiveContainer width="100%" height="100%">
            <ComposedChart data={pathData} margin={{ top: 8, right: 12, left: 0, bottom: 0 }}>
              <CartesianGrid stroke={COLORS.grid} strokeDasharray="3 3" />
              <XAxis dataKey="year" tick={{ fontSize: 12 }} />
              <YAxis
                domain={[35, 65]}
                tick={{ fontSize: 12 }}
                tickFormatter={(v) => `${v}%`}
              />
              <Tooltip formatter={(v) => fmtPct(Number(v ?? 0))} />
              <Legend />
              <Line
                type="monotone"
                dataKey="coastalMedian"
                name="Coastal median"
                stroke={COLORS.coastal}
                strokeDasharray="6 4"
                strokeWidth={1.5}
                dot={false}
              />
              <Line
                type="monotone"
                dataKey="interiorMedian"
                name="Interior median"
                stroke={COLORS.interior}
                strokeDasharray="6 4"
                strokeWidth={1.5}
                dot={false}
              />
              <Line
                type="monotone"
                dataKey="burden30"
                name={metroLabel}
                stroke="#0f172a"
                strokeWidth={2.5}
                dot={{ r: 4 }}
              />
            </ComposedChart>
          </ResponsiveContainer>
        )}

        {panel === "zori-scatter" && (
          <ResponsiveContainer width="100%" height="100%">
            <ScatterChart margin={{ top: 8, right: 12, left: 0, bottom: 8 }}>
              <CartesianGrid stroke={COLORS.grid} strokeDasharray="3 3" />
              <XAxis
                type="number"
                dataKey="zoriCumPct"
                name="ZORI %"
                tick={{ fontSize: 12 }}
                tickFormatter={(v) => `${v}%`}
                label={{ value: "ZORI cum %", position: "insideBottom", offset: -2, fontSize: 11 }}
              />
              <YAxis
                type="number"
                dataKey="burdenDeltaPp"
                name="Burden ??"
                tick={{ fontSize: 12 }}
                tickFormatter={(v) => fmtPp(v)}
                label={{ value: "Burden ?? pp", angle: -90, position: "insideLeft", fontSize: 11 }}
              />
              <ZAxis range={[60, 60]} />
              <Tooltip
                cursor={{ strokeDasharray: "3 3" }}
                content={({ active, payload }) => {
                  if (!active || !payload?.[0]) return null;
                  const p = payload[0].payload as (typeof CONVERGENCE_SCATTER)[0];
                  return (
                    <div className="rounded border border-slate-200 bg-white px-2 py-1.5 text-xs shadow">
                      <p className="font-semibold">{p.label}</p>
                      <p>ZORI {fmtPct(p.zoriCumPct)}</p>
                      <p>Burden {fmtPp(p.burdenDeltaPp)}</p>
                    </div>
                  );
                }}
              />
              <Scatter data={scatterData} name="Metros">
                {scatterData.map((r) => (
                  <Cell
                    key={r.id}
                    fill={r.cohort === "interior" ? COLORS.interior : COLORS.coastal}
                  />
                ))}
              </Scatter>
            </ScatterChart>
          </ResponsiveContainer>
        )}

        {panel === "rise-ladder" && (
          <ResponsiveContainer width="100%" height="100%">
            <BarChart
              layout="vertical"
              data={ladderData}
              margin={{ top: 4, right: 16, left: 8, bottom: 4 }}
            >
              <CartesianGrid stroke={COLORS.grid} strokeDasharray="3 3" horizontal={false} />
              <XAxis
                type="number"
                tick={{ fontSize: 12 }}
                tickFormatter={(v) =>
                  ladderMetric === "delta" ? fmtPp(v) : `${v}%`
                }
              />
              <YAxis type="category" dataKey="label" width={110} tick={{ fontSize: 11 }} />
              <Tooltip
                formatter={(v) => {
                  const n = Number(v ?? 0);
                  return ladderMetric === "delta" ? fmtPp(n) : fmtPct(n);
                }}
              />
              <Bar dataKey="value" name={ladderMetric === "delta" ? "Burden rise" : "ZORI cum"} radius={[0, 4, 4, 0]}>
                {ladderData.map((r) => (
                  <Cell key={r.label} fill={COLORS.rise} />
                ))}
              </Bar>
            </BarChart>
          </ResponsiveContainer>
        )}

        {panel === "gap-closed" && (
          <ResponsiveContainer width="100%" height="100%">
            <BarChart
              data={gapClosedData}
              margin={{ top: 8, right: 12, left: 0, bottom: 48 }}
            >
              <CartesianGrid stroke={COLORS.grid} strokeDasharray="3 3" />
              <XAxis
                dataKey="label"
                tick={{ fontSize: 10 }}
                interval={0}
                angle={-35}
                textAnchor="end"
                height={60}
              />
              <YAxis tick={{ fontSize: 12 }} tickFormatter={(v) => `${v}`} />
              <Tooltip
                formatter={(v) => `${Number(v ?? 0).toFixed(1)} pp`}
              />
              <Legend />
              <Bar dataKey="gap2019Pp" name="Gap to coastal 2019" fill="#fdba74" radius={[4, 4, 0, 0]} />
              <Bar dataKey="gap2024Pp" name="Gap to coastal 2024" fill={COLORS.closed} radius={[4, 4, 0, 0]} />
            </BarChart>
          </ResponsiveContainer>
        )}
      </div>

      <p className="text-[11px] leading-relaxed text-slate-500">{SOURCE_NOTE}</p>
    </div>
  );
}

